class Vault:
    """The module exports only this class; nothing else is expected to see the store."""
    def __init__(self, store, policy):
        self.__store, self.__policy = store, policy        # name-mangled, not enforced
    def read(self, subject, id):
        if not self.__policy.allows(subject, id):
            raise PermissionError(id)                      # decided in the same call
        return self.__store.get(id)
